const D = { energy:.5, scale:1, hue:210, wobble:.6, arms:.5, eyes:.5, spook:.4, x:.5, y:.5, speed:1, density:.5, style:'cute', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const sty=P.style, en=P.energy, t=K.t, dc=drawingContext;
const u=Math.min(width,height), sc=u*0.0044*P.scale, cx=P.x*width, cy=P.y*height;
const floatY=(0.9*Math.sin(t*0.5)+0.5*Math.sin(t*1.13+1.4))*16*sc*(0.4+en);
const floatX=(0.6*Math.sin(t*0.41+2)+0.4*Math.sin(t*0.89))*12*sc*(0.4+en);
const squash=1+Math.sin(t*1.2)*0.05*(0.5+en);

let bodyc=[0,0,99], shade=[P.hue,15,86], eyec=[0,0,10], mouthc=[0,0,10], glow=false, alphaBody=100;
if(sty==='spooky'){ bodyc=[P.hue,20,80]; shade=[P.hue,30,58]; alphaBody=82; }
else if(sty==='vapor'){ bodyc=[300,25,99]; shade=[190,30,90]; eyec=[280,40,30]; mouthc=[280,40,30]; }
else if(sty==='neon'){ bodyc=[(P.hue+140)%360,60,100]; shade=[(P.hue+140)%360,80,60]; eyec=[(P.hue+140)%360,90,20]; mouthc=[(P.hue+140)%360,90,20]; glow=true; alphaBody=85; }
else if(sty==='pixel'){ bodyc=[0,0,96]; shade=[P.hue,20,78]; eyec=[0,0,8]; }
function Cc(a,al){ return color(a[0],a[1],a[2],(al==null?100:al)*P.alpha/100); }

push();
translate(cx+floatX, cy+floatY);
scale(sc*1, sc*squash);
// body: rounded top + wavy skirt
if(glow){ dc.shadowBlur=22; dc.shadowColor=Cc(bodyc,80).toString(); }
noStroke(); fill(Cc(bodyc, alphaBody));
const bw=50, bh=64;
beginShape();
vertex(-bw,20);
bezierVertex(-bw,-bh, bw,-bh, bw,20);   // dome
const lobes=5; for(let i=lobes;i>=0;i--){ const x=-bw + (2*bw)*i/lobes; const phase=t*(2+en)+i*1.3; const y=20 + (i%2===0? 0 : 16+Math.sin(phase)*8*P.wobble); vertex(x, y); }
endShape(CLOSE);
dc.shadowBlur=0;
// inner shade
fill(Cc(shade, alphaBody*0.5)); ellipse(10,-6, bw*0.8, bh*0.7);

// arms (little nubs, wave)
const aw=Math.sin(t*1.8)*P.arms*0.5;
fill(Cc(bodyc, alphaBody));
push(); translate(-bw*0.9,-4); rotate(-0.6-aw); ellipse(0,0,22,14); pop();
push(); translate(bw*0.9,-4); rotate(0.6+aw); ellipse(0,0,22,14); pop();

// face
const es=(0.6+P.eyes*0.7);
const blink=((t*0.4+fr(2)*6)%3.2)<0.14?0.15:1;
fill(Cc(eyec,100));
if(sty==='cute'||sty==='pixel'){ ellipse(-14,-14, 12*es, 16*es*blink); ellipse(14,-14, 12*es, 16*es*blink);
  fill(0,0,100,90); circle(-16,-18,3); circle(12,-18,3);
} else { // spooky hollow eyes
  ellipse(-14,-14, 15*es, 20*es); ellipse(14,-14, 15*es, 20*es); }
// mouth
noFill(); stroke(Cc(mouthc,100)); strokeWeight(3);
const m=P.spook;
if(m<0.5){ arc(0,4,26,20, Math.PI*0.1, Math.PI*0.9); } // smile
else { ellipse(0,6,16,20+m*10); } // wail O
noStroke();
// cheek blush (cute)
if(sty==='cute'){ fill(color(0,50,100,40*P.alpha/100)); circle(-24,-2,10); circle(24,-2,10); }
blendMode(BLEND); dc.shadowBlur=0;
pop();
